"<!DOCTYPE html>
<html lang=\"tr\">
<head>
    <meta charset=\"UTF-8\">
    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">
    <title>3D Voxel Sandbox Oyunu (Minecraft Tarzı)</title>
    <style>
        body {
            margin: 0;
            overflow: hidden;
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background-color: #000;
            user-select: none;
        }
        #instructions {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            color: white;
            text-align: center;
            background: rgba(0, 0, 0, 0.8);
            padding: 30px;
            border-radius: 12px;
            border: 2px solid #4CAF50;
            cursor: pointer;
            z-index: 10;
        }
        #instructions h1 {
            color: #4CAF50;
            margin-top: 0;
        }
        #crosshair {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            width: 10px;
            height: 10px;
            border: 2px solid rgba(255, 255, 255, 0.8);
            border-radius: 50%;
            pointer-events: none;
            z-index: 5;
        }
        #hotbar {
            position: absolute;
            bottom: 20px;
            left: 50%;
            transform: translateX(-50%);
            display: flex;
            gap: 8px;
            background: rgba(0, 0, 0, 0.6);
            padding: 8px;
            border-radius: 8px;
            border: 1px solid #444;
            z-index: 5;
        }
        .slot {
            width: 45px;
            height: 45px;
            border: 2px solid #555;
            border-radius: 4px;
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            font-weight: bold;
            font-size: 14px;
            background: rgba(50, 50, 50, 0.8);
        }
        .slot.active {
            border-color: #4CAF50;
            transform: scale(1.05);
            background: rgba(76, 175, 80, 0.3);
        }
    </style>
</head>
<body>

    <div id=\"instructions\">
        <h1>3D Voxel Sandbox</h1>
        <p>Oynamak için tıklayın</p>
        <p><b>W, A, S, D:</b> Hareket Et @COMMENT_BODY@nbsp;|@COMMENT_BODY@nbsp; <b>Boşluk:</b> Zıpla</p>
        <p><b>Sol Tık:</b> Blok Kır @COMMENT_BODY@nbsp;|@COMMENT_BODY@nbsp; <b>Sağ Tık:</b> Blok Koy</p>
        <p><b>1-8 Tuşları:</b> Blok Seç</p>
    </div>

    <div id=\"crosshair\"></div>

    <div id=\"hotbar\">
        <div class=\"slot active\" data-id=\"1\">Çim</div>
        <div class=\"slot\" data-id=\"2\">Toprak</div>
        <div class=\"slot\" data-id=\"3\">Taş</div>
        <div class=\"slot\" data-id=\"4\">Tahta</div>
        <div class=\"slot\" data-id=\"5\">Yaprak</div>
        <div class=\"slot\" data-id=\"6\">Tuğla</div>
        <div class=\"slot\" data-id=\"7\">Altın</div>
        <div class=\"slot\" data-id=\"8\">Cam</div>
    </div>

    <!-- Three.js Kütüphanesi -->
    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js\"></script>
    <script>
        let camera, scene, renderer;
        let moveForward = false, moveBackward = false, moveLeft = false, moveRight = false, canJump = false;
        let velocity = new THREE.Vector3();
        let direction = new THREE.Vector3();
        let prevTime = performance.now();

        let raycaster;
        let selectedBlockType = 1;
        const blocks = [];
        const worldSize = 16;

        const blockColors = {
            1: 0x55aa55, // Çim
            2: 0x8b5a2b, // Toprak
            3: 0x888888, // Taş
            4: 0x6e4720, // Tahta
            5: 0x2e7d32, // Yaprak
            6: 0xb22222, // Tuğla
            7: 0xffd700, // Altın
            8: 0xadd8e6  // Cam
        };

        init();
        animate();

        function init() {
            scene = new THREE.Scene();
            scene.background = new THREE.Color(0x87ceeb);
            scene.fog = new THREE.FogExp2(0x87ceeb, 0.015);

            camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
            camera.position.set(8, 10, 16);

            raycaster = new THREE.Raycaster();

            // Işıklandırma
            const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
            scene.add(ambientLight);

            const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
            dirLight.position.set(50, 100, 50);
            scene.add(dirLight);

            // Zemin ve Başlangıç Dünyası (Voxel)
            const geometry = new THREE.BoxGeometry(1, 1, 1);

            for (let x = 0; x < worldSize; x++) {
                for (let z = 0; z < worldSize; z++) {
                    // Taş katmanı
                    createBlock(x, 0, z, 3);
                    // Toprak katmanı
                    createBlock(x, 1, z, 2);
                    // Çim katmanı
                    createBlock(x, 2, z, 1);

                    // Rastgele ağaçlar
                    if (x === 4 @COMMENT_BODY@@COMMENT_BODY@ z === 4) {
                        createBlock(4, 3, 4, 4);
                        createBlock(4, 4, 4, 4);
                        createBlock(4, 5, 4, 5);
                    }
                }
            }

            renderer = new THREE.WebGLRenderer({ antialias: true });
            renderer.setSize(window.innerWidth, window.innerHeight);
            document.body.appendChild(renderer.domElement);

            // Kontroller
            const instructions = document.getElementById('instructions');
            instructions.addEventListener('click', () => {
                document.body.requestPointerLock();
            });

            document.addEventListener('pointerlockchange', () => {
                if (document.pointerLockElement === document.body) {
                    instructions.style.display = 'none';
                } else {
                    instructions.style.display = 'block';
                }
            });

            document.addEventListener('keydown', onKeyDown);
            document.addEventListener('keyup', onKeyUp);
            document.addEventListener('mousedown', onMouseDown);

            // Hotbar seçimleri
            document.querySelectorAll('.slot').forEach(slot => {
                slot.addEventListener('click', (e) => {
                    document.querySelectorAll('.slot').forEach(s => s.classList.remove('active'));
                    slot.classList.add('active');
                    selectedBlockType = parseInt(slot.getAttribute('data-id'));
                });
            });

            window.addEventListener('resize', onWindowResize);
        }

        function createBlock(x, y, z, type) {
            const material = new THREE.MeshLambertMaterial({ 
                color: blockColors[type],
                transparent: type === 8,
                opacity: type === 8 ? 0.6 : 1.0
            });
            const mesh = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), material);
            mesh.position.set(x + 0.5, y + 0.5, z + 0.5);
            mesh.userData = { type: type };
            scene.add(mesh);
            blocks.push(mesh);
        }

        function onKeyDown(event) {
            switch (event.code) {
                case 'KeyW': moveForward = true; break;
                case 'KeyS': moveBackward = true; break;
                case 'KeyA': moveLeft = true; break;
                case 'KeyD': moveRight = true; break;
                case 'Space':
                    if (canJump === true) velocity.y += 8;
                    canJump = false;
                    break;
                case 'Digit1': case 'Digit2': case 'Digit3': case 'Digit4':
                case 'Digit5': case 'Digit6': case 'Digit7': case 'Digit8':
                    const idx = parseInt(event.key) - 1;
                    document.querySelectorAll('.slot').forEach((s, i) => {
                        s.classList.toggle('active', i === idx);
                    });
                    selectedBlockType = parseInt(event.key);
                    break;
            }
        }

        function onKeyUp(event) {
            switch (event.code) {
                case 'KeyW': moveForward = false; break;
                case 'KeyS': moveBackward = false; break;
                case 'KeyA': moveLeft = false; break;
                case 'KeyD': moveRight = false; break;
            }
        }

        function onMouseDown(event) {
            if (document.pointerLockElement !== document.body) return;

            raycaster.setFromCamera(new THREE.Vector2(0, 0), camera);
            const intersects = raycaster.intersectObjects(blocks);

            if (intersects.length > 0) {
                const intersect = intersects[0];

                if (event.button === 0) {
                    // Sol tık: Blok Kır
                    scene.remove(intersect.object);
                    const index = blocks.indexOf(intersect.object);
                    if (index > -1) blocks.splice(index, 1);
                } else if (event.button === 2) {
                    // Sağ tık: Blok Koy
                    const pos = intersect.point.clone().add(intersect.face.normal.clone().multiplyScalar(0.5));
                    const x = Math.floor(pos.x);
                    const y = Math.floor(pos.y);
                    const z = Math.floor(pos.z);
                    createBlock(x, y, z, selectedBlockType);
                }
            }
        }

        function onWindowResize() {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }

        function animate() {
            requestAnimationFrame(animate);

            const time = performance.now();
            const delta = (time - prevTime) / 1000;

            if (document.pointerLockElement === document.body) {
                velocity.x -= velocity.x * 10.0 * delta;
                velocity.z -= velocity.z * 10.0 * delta;
                velocity.y -= 9.8 * 4.0 * delta; // Yerçekimi

                direction.z = Number(moveForward) - Number(moveBackward);
                direction.x = Number(moveRight) - Number(moveLeft);
                direction.normalize();

                if (moveForward || moveBackward) velocity.z -= direction.z * 40.0 * delta;
                if (moveLeft || moveRight) velocity.x -= direction.x * 40.0 * delta;

                camera.translateX(velocity.x * delta);
                camera.translateZ(velocity.z * delta);
                camera.position.y += (velocity.y * delta);

                if (camera.position.y < 3) {
                    velocity.y = 0;
                    camera.position.y = 3;
                    canJump = true;
                }
            }

            prevTime = time;
            renderer.render(scene, camera);
        }
    </script>
</body>
</html>

